CREATE VIEW IF NOT EXISTS _warehouse_prefix_names_v88 AS SELECT DISTINCT code.value AS old_code, substr(code.value,2) AS new_code FROM settings, json_each(settings.value) zone, json_each(zone.value,'$.codes') code WHERE settings.key='warehouse_zones' AND json_extract(zone.value,'$.id') IN ('NEW_A','NEW_B','NEW_C','NEW_D') AND substr(code.value,1,2) IN ('新A','新B','新C','新D') AND code.value NOT IN ('新B33','新B34') AND length(code.value)>2 AND substr(code.value,3) NOT GLOB '*[^0-9]*';
--> statement-breakpoint
CREATE VIEW IF NOT EXISTS _warehouse_prefix_source_v91 AS SELECT json_group_array(json(iif(json_extract(zone.value,'$.id')='NEW_B',json_set(zone.value,'$.codes',json((SELECT json_group_array(code.value) FROM json_each(zone.value,'$.codes') code WHERE code.value NOT IN ('新B33','新B34'))),'$.layout',json_remove(COALESCE(json_extract(zone.value,'$.layout'),'{}'),'$.新B33','$.新B34')),zone.value))) AS value FROM settings,json_each(settings.value) zone WHERE settings.key='warehouse_location_prefix_backup_v1';
--> statement-breakpoint
CREATE VIEW IF NOT EXISTS _warehouse_prefix_zones_v91 AS SELECT (SELECT json_group_array(json(CASE WHEN json_extract(zone.value,'$.id') IN ('NEW_A','NEW_B','NEW_C','NEW_D') THEN CASE WHEN json_type(zone.value,'$.features')='array' THEN json_set(json_set(zone.value,'$.locationCodesVersion',1,'$.title',replace(CASE WHEN substr(json_extract(zone.value,'$.title'),1,3) IN ('新A区','新B区','新C区','新D区') THEN substr(json_extract(zone.value,'$.title'),2) ELSE json_extract(zone.value,'$.title') END,' · 新库位',' · 库位'),'$.codes',json((SELECT json_group_array(value) FROM (SELECT COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=code.value),code.value) AS value, min(CAST(code.key AS INTEGER)) AS position FROM json_each(zone.value,'$.codes') code GROUP BY COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=code.value),code.value) ORDER BY position))),'$.layout',json(CASE WHEN json_extract(zone.value,'$.id')='NEW_B' AND EXISTS (SELECT 1 FROM _warehouse_prefix_names_v88 WHERE old_code='新B3') AND (SELECT json_extract(z.value,'$.layout.B3') FROM json_each((SELECT value FROM _warehouse_prefix_source_v91)) z WHERE EXISTS (SELECT 1 FROM json_each(z.value,'$.codes') c WHERE c.value='B3') AND json_type(z.value,'$.layout.B3')='object' ORDER BY (json_extract(z.value,'$.id')='NEW_B') DESC LIMIT 1) IS NOT NULL THEN json_set((SELECT json_group_object(COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=box.key),box.key),json(box.value)) FROM json_each(zone.value,'$.layout') box WHERE NOT (box.key='新B3' AND json_type(zone.value,'$.layout.B3')='object')),'$.B3',json((SELECT json_extract(z.value,'$.layout.B3') FROM json_each((SELECT value FROM _warehouse_prefix_source_v91)) z WHERE EXISTS (SELECT 1 FROM json_each(z.value,'$.codes') c WHERE c.value='B3') AND json_type(z.value,'$.layout.B3')='object' ORDER BY (json_extract(z.value,'$.id')='NEW_B') DESC LIMIT 1))) ELSE (SELECT json_group_object(COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=box.key),box.key),json(box.value)) FROM json_each(zone.value,'$.layout') box WHERE NOT (box.key='新B3' AND json_type(zone.value,'$.layout.B3')='object')) END)),'$.features',json((SELECT json_group_array(json(CASE WHEN json_extract(feature.value,'$.label') IN ('新A区','新B区','新C区','新D区') THEN json_set(feature.value,'$.label',substr(json_extract(feature.value,'$.label'),2)) ELSE feature.value END)) FROM json_each(zone.value,'$.features') feature))) ELSE json_set(zone.value,'$.locationCodesVersion',1,'$.title',replace(CASE WHEN substr(json_extract(zone.value,'$.title'),1,3) IN ('新A区','新B区','新C区','新D区') THEN substr(json_extract(zone.value,'$.title'),2) ELSE json_extract(zone.value,'$.title') END,' · 新库位',' · 库位'),'$.codes',json((SELECT json_group_array(value) FROM (SELECT COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=code.value),code.value) AS value, min(CAST(code.key AS INTEGER)) AS position FROM json_each(zone.value,'$.codes') code GROUP BY COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=code.value),code.value) ORDER BY position))),'$.layout',json(CASE WHEN json_extract(zone.value,'$.id')='NEW_B' AND EXISTS (SELECT 1 FROM _warehouse_prefix_names_v88 WHERE old_code='新B3') AND (SELECT json_extract(z.value,'$.layout.B3') FROM json_each((SELECT value FROM _warehouse_prefix_source_v91)) z WHERE EXISTS (SELECT 1 FROM json_each(z.value,'$.codes') c WHERE c.value='B3') AND json_type(z.value,'$.layout.B3')='object' ORDER BY (json_extract(z.value,'$.id')='NEW_B') DESC LIMIT 1) IS NOT NULL THEN json_set((SELECT json_group_object(COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=box.key),box.key),json(box.value)) FROM json_each(zone.value,'$.layout') box WHERE NOT (box.key='新B3' AND json_type(zone.value,'$.layout.B3')='object')),'$.B3',json((SELECT json_extract(z.value,'$.layout.B3') FROM json_each((SELECT value FROM _warehouse_prefix_source_v91)) z WHERE EXISTS (SELECT 1 FROM json_each(z.value,'$.codes') c WHERE c.value='B3') AND json_type(z.value,'$.layout.B3')='object' ORDER BY (json_extract(z.value,'$.id')='NEW_B') DESC LIMIT 1))) ELSE (SELECT json_group_object(COALESCE((SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=box.key),box.key),json(box.value)) FROM json_each(zone.value,'$.layout') box WHERE NOT (box.key='新B3' AND json_type(zone.value,'$.layout.B3')='object')) END)) END WHEN EXISTS (SELECT 1 FROM _warehouse_prefix_names_v88 WHERE old_code='新B3') AND EXISTS (SELECT 1 FROM json_each(zone.value,'$.codes') c WHERE c.value='B3') THEN json_set(zone.value,'$.codes',json((SELECT json_group_array(code.value) FROM json_each(zone.value,'$.codes') code WHERE code.value<>'B3')),'$.layout',json_remove(COALESCE(json_extract(zone.value,'$.layout'),'{}'),'$.B3')) ELSE zone.value END)) FROM json_each((SELECT value FROM _warehouse_prefix_source_v91)) zone) AS value;
