CREATE TRIGGER IF NOT EXISTS warehouse_prefix_repair_v88 AFTER INSERT ON settings WHEN NEW.key='warehouse_location_prefix_backup_v1' AND NOT EXISTS (SELECT 1 FROM settings WHERE key='warehouse_location_prefix_repair_v1') BEGIN SELECT RAISE(ABORT,'库位更名中止：四个区域资料不完整') WHERE (SELECT count(*) FROM json_each(NEW.value) WHERE json_extract(value,'$.id') IN ('NEW_A','NEW_B','NEW_C','NEW_D'))<>4; SELECT RAISE(ABORT,'库位更名中止：重复库位已有货物，请先核对') WHERE EXISTS (SELECT 1 FROM stocks WHERE upper(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(location_code,'Ａ','A'),'Ｂ','B'),'Ｃ','C'),'Ｄ','D'),'ａ','a'),'ｂ','b'),'ｃ','c'),'ｄ','d'),'０','0'),'１','1'),'２','2'),'３','3'),'４','4'),'５','5'),'６','6'),'７','7'),'８','8'),'９','9'),'　',' '))) IN ('新B3','新B33','新B34')); SELECT RAISE(ABORT,'库位更名中止：除B3外发现其他同名库位') WHERE EXISTS ( SELECT 1 FROM _warehouse_prefix_names_v88 names WHERE names.new_code<>'B3' AND ( EXISTS (SELECT 1 FROM stocks WHERE upper(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(location_code,'Ａ','A'),'Ｂ','B'),'Ｃ','C'),'Ｄ','D'),'ａ','a'),'ｂ','b'),'ｃ','c'),'ｄ','d'),'０','0'),'１','1'),'２','2'),'３','3'),'４','4'),'５','5'),'６','6'),'７','7'),'８','8'),'９','9'),'　',' ')))=upper(names.new_code)) OR EXISTS (SELECT 1 FROM json_each(NEW.value) z, json_each(z.value,'$.codes') c WHERE upper(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(c.value,'Ａ','A'),'Ｂ','B'),'Ｃ','C'),'Ｄ','D'),'ａ','a'),'ｂ','b'),'ｃ','c'),'ｄ','d'),'０','0'),'１','1'),'２','2'),'３','3'),'４','4'),'５','5'),'６','6'),'７','7'),'８','8'),'９','9'),'　',' ')))=upper(names.new_code)) ) ); SELECT RAISE(ABORT,'库位更名中止：历史名称已经指向其他库位') WHERE EXISTS ( SELECT 1 FROM _warehouse_prefix_names_v88 n, settings s, json_each(s.value) a WHERE s.key='warehouse_location_aliases' AND a.key=n.old_code AND a.value<>n.new_code ); INSERT INTO settings(key,value,updated_at) VALUES ('warehouse_location_prefix_repair_v1','{"status":"applying"}',strftime('%Y-%m-%dT%H:%M:%fZ','now')); INSERT INTO settings(key,value,updated_at) SELECT 'warehouse_location_aliases',json_patch(COALESCE((SELECT value FROM settings WHERE key='warehouse_location_aliases'),'{}'),(SELECT json_group_object(old_code,new_code) FROM _warehouse_prefix_names_v88)),strftime('%Y-%m-%dT%H:%M:%fZ','now') ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at; UPDATE stocks SET location_code=(SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=stocks.location_code) WHERE location_code IN (SELECT old_code FROM _warehouse_prefix_names_v88); UPDATE storage_fee_settlements SET location_code=(SELECT new_code FROM _warehouse_prefix_names_v88 WHERE old_code=storage_fee_settlements.location_code) WHERE location_code IN (SELECT old_code FROM _warehouse_prefix_names_v88); UPDATE settings SET value=(SELECT value FROM _warehouse_prefix_zones_v91),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE key='warehouse_zones'; SELECT RAISE(ABORT,'库位更名校验失败：仍有新字开头的编号') WHERE EXISTS (SELECT 1 FROM _warehouse_prefix_names_v88); SELECT RAISE(ABORT,'库位更名校验失败：B3编号数量不正确') WHERE (SELECT count(*) FROM json_each((SELECT value FROM settings WHERE key='warehouse_zones')) z,json_each(z.value,'$.codes') c WHERE c.value='B3')<>1; SELECT RAISE(ABORT,'库位更名校验失败：编号重复') WHERE EXISTS (SELECT c.value FROM json_each((SELECT value FROM settings WHERE key='warehouse_zones')) z,json_each(z.value,'$.codes') c GROUP BY upper(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(c.value,'Ａ','A'),'Ｂ','B'),'Ｃ','C'),'Ｄ','D'),'ａ','a'),'ｂ','b'),'ｃ','c'),'ｄ','d'),'０','0'),'１','1'),'２','2'),'３','3'),'４','4'),'５','5'),'６','6'),'７','7'),'８','8'),'９','9'),'　',' '))) HAVING count(*)>1); UPDATE settings SET value=json_object('status','done','version',91,'extraGeneratedCodeCount',(SELECT count(*) FROM json_each((SELECT value FROM settings WHERE key='warehouse_zones')) z,json_each(z.value,'$.codes') c WHERE c.value IN ('新B33','新B34')),'totalLocationCount',(SELECT count(*) FROM json_each((SELECT value FROM settings WHERE key='warehouse_zones')) z,json_each(z.value,'$.codes')),'remainingPrefixedCodes',(SELECT count(*) FROM _warehouse_prefix_names_v88),'b3LocationCount',(SELECT count(*) FROM json_each((SELECT value FROM settings WHERE key='warehouse_zones')) z,json_each(z.value,'$.codes') c WHERE c.value='B3'),'stockCount',(SELECT count(*) FROM stocks)),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE key='warehouse_location_prefix_repair_v1'; END;
--> statement-breakpoint
INSERT INTO settings(key,value,updated_at) SELECT 'warehouse_location_prefix_backup_v1',value,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM settings WHERE key='warehouse_zones' AND NOT EXISTS (SELECT 1 FROM settings WHERE key='warehouse_location_prefix_repair_v1');
--> statement-breakpoint
DROP TRIGGER IF EXISTS warehouse_prefix_repair_v88;
--> statement-breakpoint
DROP VIEW IF EXISTS _warehouse_prefix_zones_v91;
